CustomField.formula:
12 * (
   ( 5 * FLOOR( ( DATEVALUE( ClosedDate ) - DATE( 1900, 1, 8) ) / 7) +
    MIN(5, 
     MOD( DATEVALUE( ClosedDate ) - DATE( 1900, 1, 8), 7) +
     MIN( 1, 24 / 12 * ( MOD( ClosedDate - DATETIMEVALUE( '1900-01-08 12:00:00' ), 1 ) ) )
    ) 
   )
 -
   ( 5 * FLOOR( ( DATEVALUE( NSP_Owner_Assign_Date__c ) - DATE( 1900, 1, 8) ) / 7) +
     MIN( 5,
      MOD( DATEVALUE( NSP_Owner_Assign_Date__c ) - DATE( 1996, 1, 1), 7 ) +
      MIN( 1, 24 / 12 * ( MOD( NSP_Owner_Assign_Date__c - DATETIMEVALUE( '1900-01-08 12:00:00' ), 1) ) )
    )
   ) 
  )
